"allergy": "IF NOT EXISTS (SELECT TOP (1) * FROM emar..patient_allergies WHERE patient_id = {{patientId}} AND (allergy_drug_id = '{{AR_allergyDrugId}}' OR class = {{AR_allergyClass}} OR category = {{AR_allergyCategory}})) BEGIN INSERT INTO emar..patient_allergies (patient_id,class,category,name,allergy_drug_id,is_active,reaction,severity,add_user_id,add_datetime,change_user_id,action_status,information_source) VALUES ({{patientId}},0,0,'{{AR_allergyName}}','{{AR_allergyDrugId}}',1,'ALGRXNRASH','SEV1',4545,'{{currentDt}}',0,'C','PC') END SELECT TOP (1) * FROM emar..patient_allergies WHERE patient_id = {{patientId}} AND (allergy_drug_id = '{{AR_allergyDrugId}}' OR class = {{AR_allergyClass}} OR category = {{AR_allergyCategory}})",
